@namespace sv_3a988489728a45dc9bd3ca5d72da985a.Components.JobApplication

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < _references.Count; i++)
    {
        var index = i;
        var r = _references[index];
        <ReferenceForm
            Index="index"
            Name="@r.Name"
            Relationship="@r.Relationship"
            Email="@r.Email"
            Phone="@r.Phone"
            CanRemove="@(_references.Count > 2)"
            OnRemove="() => RemoveReference(index)"
            OnChanged="data => UpdateReference(index, data)" />
    }

    @if (_references.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Models.Reference>? InitialReferences { get; set; }
    [Parameter] public EventCallback<List<Models.Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<RefModel> _references = new();
    private string? _validationError;

    protected override void OnInitialized()
    {
        if (InitialReferences is { Count: > 0 })
        {
            _references = InitialReferences.Select(r => new RefModel
            {
                Name = r.Name,
                Relationship = r.Relationship,
                Email = r.Email,
                Phone = r.Phone
            }).ToList();
        }
        else
        {
            _references.Add(new RefModel());
            _references.Add(new RefModel());
        }
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new RefModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        if (index < _references.Count)
        {
            _references[index] = new RefModel
            {
                Name = data.Name,
                Relationship = data.Relationship,
                Email = data.Email,
                Phone = data.Phone
            };
        }
    }

    private async Task HandleNext()
    {
        _validationError = null;

        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _validationError = "All fields are required for each reference.";
                return;
            }
        }

        var refs = _references.Select(r =>
            new Models.Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

        await OnNext.InvokeAsync(refs);
    }

    private class RefModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_3a988489728a45dc9bd3ca5d72da985a.Components.JobApplication

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" @bind="Text" @bind:event="oninput"
                  class="form-control cover-letter-textarea"
                  rows="12" maxlength="@MaxLength"></textarea>
        <span class="char-count @(Text.Length > MaxLength ? "over-limit" : "")">
            @Text.Length / @MaxLength characters
        </span>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string Text { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private string? _validationError;

    private async Task HandleNext()
    {
        _validationError = null;

        if (string.IsNullOrWhiteSpace(Text))
        {
            _validationError = "Please write a cover letter.";
            return;
        }

        if (Text.Length > MaxLength)
        {
            _validationError = $"Cover letter must be {MaxLength} characters or fewer.";
            return;
        }

        await OnNext.InvokeAsync(Text);
    }
}

@namespace sv_3a988489728a45dc9bd3ca5d72da985a.Components.JobApplication

<div class="step-content">
    <h2>Review &amp; Submit</h2>

    @if (_submitted)
    {
        <div class="confirmation">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application ID is: <strong>@_applicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-section-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            @if (Personal is not null)
            {
                <dl class="review-details">
                    <dt>Full Name</dt><dd>@Personal.FullName</dd>
                    <dt>Email</dt><dd>@Personal.Email</dd>
                    <dt>Phone</dt><dd>@Personal.Phone</dd>
                    <dt>Address</dt><dd>@Personal.Address</dd>
                </dl>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
