@code {
    [Parameter] public List<Models.Reference>? InitialReferences { get; set; }
    [Parameter] public EventCallback<List<Models.Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<RefModel> _references = new();
    private string? _validationError;

    protected override void OnInitialized()
    {
        if (InitialReferences is { Count: > 0 })
        {
            _references = InitialReferences.Select(r => new RefModel
            {
                Name = r.Name,
                Relationship = r.Relationship,
                Email = r.Email,
                Phone = r.Phone
            }).ToList();
        }
        else
        {
            _references.Add(new RefModel());
            _references.Add(new RefModel());
        }
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new RefModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        if (index < _references.Count)
        {
            _references[index] = new RefModel
            {
                Name = data.Name,
                Relationship = data.Relationship,
                Email = data.Email,
                Phone = data.Phone
            };
        }
    }

    private async Task HandleNext()
    {
        _validationError = null;

        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _validationError = "All fields are required for each reference.";
                return;
