"}

{"path": "/tmp/sv-3a988489728a45dc9bd3ca5d72da985a/Components/JobApplication/ReviewStep.razor", "file_text": "@namespace sv_3a988489728a45dc9bd3ca5d72da985a.Components.JobApplication

<div class="step-content">
    <h2>Review &amp; Submit</h2>

    @if (_submitted)
    {
        <div class="confirmation">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application ID is: <strong>@_applicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-section-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            @if (Personal is not null)
            {
                <dl class="review-details">
                    <dt>Full Name</dt><dd>@Personal.FullName</dd>
                    <dt>Email</dt><dd>@Personal.Email</dd>
                    <dt>Phone</dt><dd>@Personal.Phone</dd>
                    <dt>Address</dt><dd>@Personal.Address</dd>
                </dl>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @if (Work is not null)
            {
                @foreach (var entry in Work.Entries)
                {
                    <div class="review-work-entry">
                        <strong>@entry.Title</strong> at @entry.Company
                        <br />
                        <span class="review-date">@entry.StartDate.ToString("MMM yyyy") – @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</span>
                        <p>@entry.Description</p>
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="review-reference">
                        <strong>@r.Name</strong> (@r.Relationship)
                        <br />@r.Email | @r.Phone
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(_error))
        {
            <div class="validation-summary">@_error</div>
        }

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@_isSubmitting">
                @(_isSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public Models.PersonalInfo? Personal { get; set; }
    [Parameter] public Models.WorkHistory? Work { get; set; }
    [Parameter] public List<Models.Reference>? References { get; set; }
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string? _error;

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        _isSubmitting = true;
        _error = null;

        try
        {
            _applicationId = await OnSubmit();
            _submitted = true;
        }
        catch (Exception ex)
        {
            _error = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}
"}

