@namespace sv_3a988489728a45dc9bd3ca5d72da985a.Components.JobApplication

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" @bind="Text" @bind:event="oninput"
                  class="form-control cover-letter-textarea"
                  rows="12" maxlength="@MaxLength"></textarea>
        <span class="char-count @(Text.Length > MaxLength ? "over-limit" : "")">
            @Text.Length / @MaxLength characters
        </span>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string Text { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private string? _validationError;

    private async Task HandleNext()
    {
        _validationError = null;

        if (string.IsNullOrWhiteSpace(Text))
        {
            _validationError = "Please write a cover letter.";
            return;
        }

        if (Text.Length > MaxLength)
        {
            _validationError = $"Cover letter must be {MaxLength} characters or fewer.";
            return;
        }

        await OnNext.InvokeAsync(Text);
    }
}

