arguments.file_text:
namespace sv_3a988489728a45dc9bd3ca5d72da985a.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_3a988489728a45dc9bd3ca5d72da985a.Models
@using sv_3a988489728a45dc9bd3ca5d72da985a.Components.JobApplication
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator
        CurrentStep="_currentStep"
        StepNames="_stepNames"
        CompletedSteps="_completedSteps"
        OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@(_personalInfo?.FullName ?? "")"
                Email="@(_personalInfo?.Email ?? "")"
                Phone="@(_personalInfo?.Phone ?? "")"
                Address="@(_personalInfo?.Address ?? "")"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalInfoNext" />
            break;

        case 1:
            <WorkHistoryStep
                InitialEntries="@_workHistory?.Entries"
                OnNext="HandleWorkHistoryNext"
                OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep
                InitialReferences="@_references"
                OnNext="HandleReferencesNext"
                OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep
                Text="@_coverLetter"
                OnNext="HandleCoverLetterNext"
                OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep
                Personal="_personalInfo"
                Work="_workHistory"
                References="_references"
                CoverLetter="@_coverLetter"
                OnEditSection="GoToStep"
                OnBack="GoBack"
                OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private readonly HashSet<int> _completedSteps = new();

    private static readonly IReadOnlyList<string> _stepNames = new[]
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private PersonalInfo? _personalInfo;
    private WorkHistory? _workHistory;
    private List<Reference>? _references;
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
            _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        _personalInfo = info;
        _completedSteps.Add(0);
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(WorkHistory work)
    {
        _workHistory = work;
        _completedSteps.Add(1);
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        _references = refs;
        _completedSteps.Add(2);
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        _coverLetter = text;
        _completedSteps.Add(3);
        _currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(_personalInfo!, _workHistory!, _references!, _coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.application-form {
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
    position: relative;
}

.step-list::before {
    content: '';
    position: absolute;
    top: 18px;
    left: 10%;
    right: 10%;
    height: 2px;
    background: #e0e0e0;
    z-index: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    z-index: 1;
    flex: 1;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: default;
    padding: 0;
    gap: 0.5rem;
}

.completed .step-button {
    cursor: pointer;
}

.step-icon {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.875rem;
    background: #e0e0e0;
    color: #999;
}

.step-item.active .step-icon {
    background: #2563eb;
    color: white;
}

.step-item.completed .step-icon {
    background: #16a34a;
    color: white;
}

.step-item.future .step-icon {
    background: #e0e0e0;
    color: #999;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
    max-width: 80px;
}

.step-item.active .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #16a34a;
}

/* Step Content */
.step-content {
    background: white;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1f2937;
}

.step-description {
    color: #6b7280;
    margin-bottom: 1rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    color: #374151;
    font-size: 0.875rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.9rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e5e7eb;
}

.btn {
    padding: 0.6rem 1.5rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: background 0.15s, opacity 0.15s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #2563eb;
    color: white;
    margin-left: auto;
}

.btn-primary:hover:not(:disabled) {
    background: #1d4ed8;
}

.btn-outline {
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
}

.btn-outline:hover {
    background: #f9fafb;
}

.btn-secondary {
    background: #f3f4f6;
    color: #374151;
    border: 1px solid #d1d5db;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e5e7eb;
}

.btn-danger {
    background: #dc2626;
    color: white;
}

.btn-danger:hover {
    background: #b91c1c;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

.btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #1d4ed8;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Validation */
.validation-summary {
    background: #fef2f2;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-top: 1rem;
    font-size: 0.875rem;
}

.field-error {
    color: #dc2626;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

/* Work Entry / Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    color: #374151;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
    font-family: inherit;
}

.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.375rem;
}

.char-count.over-limit {
    color: #dc2626;
    font-weight: 600;
}

/* Review Step */
.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #1f2937;
}

.review-details {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.375rem 1rem;
    margin: 0;
}

.review-details dt {
    font-weight: 500;
    color: #6b7280;
    font-size: 0.875rem;
}

.review-details dd {
    margin: 0;
    font-size: 0.875rem;
}

.review-work-entry {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f3f4f6;
}

.review-work-entry:last-child {
    border-bottom: none;
}

.review-date {
    font-size: 0.8rem;
    color: #6b7280;
}

.review-reference {
    padding: 0.5rem 0;
}

.review-cover-letter {
    white-space: pre-wrap;
    font-size: 0.875rem;
    color: #374151;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h3 {
    color: #16a34a;
    font-size: 1.5rem;
}

