    color: #2563eb;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #1d4ed8;
}

.btn-submit {
    padding: 0.75rem 2rem;
